create table if not exists public.seller_academy_articles(id uuid primary key default gen_random_uuid(),category text not null,title text not null,summary text not null default '',steps jsonb not null default '[]'::jsonb,is_published boolean not null default true,sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); alter table public.seller_academy_articles enable row level security; drop policy if exists seller_academy_public_read on public.seller_academy_articles; create policy seller_academy_public_read on public.seller_academy_articles for select to authenticated using(is_published=true); create index if not exists idx_seller_academy_category_order on public.seller_academy_articles(category,sort_order); insert into public.seller_academy_articles(category,title,summary,steps,sort_order) values
("account","Set up your seller account","Complete the basic seller profile before listing products.","[{\"text\":\"Sign in and open Seller Dashboard.\",\"title\":\"Open Seller Dashboard\"},{\"text\":\"Add the business and contact information requested by the platform.\",\"title\":\"Complete profile\"},{\"text\":\"Confirm the saved details before moving to store setup.\",\"title\":\"Save and review\"}]"::jsonb,10),
("verification","Seller verification","Understand the verification flow and keep submitted information consistent.","[{\"text\":\"Check the verification information requested by Apna Store.\",\"title\":\"Review requirements\"},{\"text\":\"Use your own valid business information and documents where requested.\",\"title\":\"Submit accurate details\"},{\"text\":\"Use the seller account or support flow for the actual verification status.\",\"title\":\"Track the result\"}]"::jsonb,20),
("store","Set up your store","Prepare the seller storefront for customers.","[{\"text\":\"Go to your seller store settings.\",\"title\":\"Open store settings\"},{\"text\":\"Enter the store information supported by the current seller profile.\",\"title\":\"Add store information\"},{\"text\":\"Open the customer-facing store view and check the information.\",\"title\":\"Review storefront\"}]"::jsonb,30),
("listing","Create a product listing","Create a listing using real product information.","[{\"text\":\"Choose the seller listing/product management area.\",\"title\":\"Open Listings\"},{\"text\":\"Add the real title, description, category, price and stock information.\",\"title\":\"Enter product details\"},{\"text\":\"Check required fields and submit through the existing listing workflow.\",\"title\":\"Validate and submit\"}]"::jsonb,40),
("images","Add product images","Use clear product images and the existing secure image upload flow.","[{\"text\":\"Edit the product and open its image section.\",\"title\":\"Open product images\"},{\"text\":\"Select supported product images through the secure upload control.\",\"title\":\"Upload images\"},{\"text\":\"Confirm the correct images are associated with the product before saving.\",\"title\":\"Review selection\"}]"::jsonb,50),
("variants","Set up variants","Organize size, color or other supported product variants.","[{\"text\":\"Edit the product and open variant management.\",\"title\":\"Open variants\"},{\"text\":\"Enter only real variant options and their corresponding inventory information.\",\"title\":\"Add variant values\"},{\"text\":\"Review each variant before publishing or updating the listing.\",\"title\":\"Save and verify\"}]"::jsonb,60),
("sku","Manage SKU","Keep SKU values consistent for product and inventory operations.","[{\"text\":\"Find the SKU field in the product management workflow.\",\"title\":\"Open product inventory\"},{\"text\":\"Use the seller’s real SKU convention and avoid duplicate identifiers.\",\"title\":\"Enter a unique SKU\"},{\"text\":\"Confirm the SKU remains associated with the intended product or variant.\",\"title\":\"Save and verify\"}]"::jsonb,70),
("pricing","Set product pricing","Review price and compare-at-price before publishing.","[{\"text\":\"Edit the product pricing section.\",\"title\":\"Open pricing\"},{\"text\":\"Use the actual selling price and supported comparison price.\",\"title\":\"Enter real prices\"},{\"text\":\"Confirm the customer-facing price is accurate before saving.\",\"title\":\"Review discount display\"}]"::jsonb,80),
("stock","Manage inventory","Keep stock quantities aligned with actual inventory.","[{\"text\":\"Go to the seller inventory/product management area.\",\"title\":\"Open inventory\"},{\"text\":\"Enter the real available quantity for the product or variant.\",\"title\":\"Update quantity\"},{\"text\":\"Check the customer-facing listing after saving.\",\"title\":\"Verify availability\"}]"::jsonb,90),
("orders","Process seller orders","Follow the existing seller order lifecycle without inventing shipment data.","[{\"text\":\"Review new and actionable orders assigned to your products.\",\"title\":\"Open Seller Orders\"},{\"text\":\"Follow the actual packing and readiness workflow.\",\"title\":\"Prepare the order\"},{\"text\":\"Create or manage shipment only through the real courier workflow when required.\",\"title\":\"Use shipping tools\"}]"::jsonb,100),
("pickup","Prepare pickup","Use the configured seller pickup information for a real shipment.","[{\"text\":\"Verify the seller pickup address and contact details.\",\"title\":\"Check pickup details\"},{\"text\":\"Ensure required weight and dimensions are available.\",\"title\":\"Confirm shipment readiness\"},{\"text\":\"Use the courier action only after a real shipment exists.\",\"title\":\"Schedule real pickup\"}]"::jsonb,110),
("shipment","Create a shipment","Create shipments only for eligible real seller orders.","[{\"text\":\"Open a seller-owned order that is ready for shipment.\",\"title\":\"Select an eligible order\"},{\"text\":\"Confirm shipping address, weight and dimensions.\",\"title\":\"Validate package data\"},{\"text\":\"Use the existing courier shipment workflow and keep the returned shipment identifiers.\",\"title\":\"Create shipment\"}]"::jsonb,120),
("courier","Use courier tools","Manage real courier actions and tracking.","[{\"text\":\"Use the courier serviceability tool for the destination.\",\"title\":\"Check serviceability\"},{\"text\":\"Use the real courier assignment action; do not enter a fake AWB.\",\"title\":\"Assign AWB when available\"},{\"text\":\"Use the actual tracking action and shipment events.\",\"title\":\"Track shipment\"}]"::jsonb,130),
("sales","Review sales","Use seller analytics to understand actual sales activity.","[{\"text\":\"Open the seller analytics area.\",\"title\":\"Open Growth or Analytics\"},{\"text\":\"Select the reporting period available in the dashboard.\",\"title\":\"Choose a period\"},{\"text\":\"Use displayed database-backed sales, orders and product metrics.\",\"title\":\"Review actual metrics\"}]"::jsonb,140),
("offers","Manage offers","Create or review supported seller offers.","[{\"text\":\"Use the existing seller promotion controls.\",\"title\":\"Open Sales or Offers\"},{\"text\":\"Select a supported discount or offer structure.\",\"title\":\"Choose an offer type\"},{\"text\":\"Review schedule and constraints before activating the offer.\",\"title\":\"Set dates and limits\"}]"::jsonb,150),
("coupons","Create a coupon","Set up a seller coupon using the existing coupon center.","[{\"text\":\"Go to the seller coupon management area.\",\"title\":\"Open Coupon Center\"},{\"text\":\"Set the supported minimum cart value, discount and usage limits.\",\"title\":\"Configure rules\"},{\"text\":\"Check expiry and eligibility rules before activating the coupon.\",\"title\":\"Review and publish\"}]"::jsonb,160),
("analytics","Use seller analytics","Read product and business metrics without relying on fabricated numbers.","[{\"text\":\"Open the seller Growth or Analytics dashboard.\",\"title\":\"Open analytics\"},{\"text\":\"Choose a valid date range and compare available metrics.\",\"title\":\"Compare periods\"},{\"text\":\"Use actual product views, sales, conversion and inventory information shown by the system.\",\"title\":\"Act on real signals\"}]"::jsonb,170),
("ads","Create an ad campaign","Set up sponsored product advertising.","[{\"text\":\"Open the seller Advertising Center.\",\"title\":\"Open Advertising Center\"},{\"text\":\"Set product/category/keyword targeting and supported budget fields.\",\"title\":\"Choose targeting and budget\"},{\"text\":\"Use actual impressions and clicks; spend/orders/ROAS remain unavailable until real attribution is connected.\",\"title\":\"Review campaign metrics\"}]"::jsonb,180),
("payments","Review seller payments","Understand the seller payment and payout information available in the account.","[{\"text\":\"Use the seller payment area.\",\"title\":\"Open payments or payouts\"},{\"text\":\"Check settlement and payout records returned for your seller account.\",\"title\":\"Review actual records\"},{\"text\":\"If a record is unavailable, use Support rather than assuming a payment succeeded.\",\"title\":\"Resolve missing records\"}]"::jsonb,190),
("returns","Handle returns","Follow the real return-management workflow.","[{\"text\":\"Review return requests for your products.\",\"title\":\"Open returns\"},{\"text\":\"Review the real reason, status and associated order item.\",\"title\":\"Check request details\"},{\"text\":\"Approve, reject or manage the return only through the authorized workflow.\",\"title\":\"Use available actions\"}]"::jsonb,200),
("exchange","Handle exchanges","Manage exchange requests using actual return records.","[{\"text\":\"Review the exchange request and associated order item.\",\"title\":\"Open the return request\"},{\"text\":\"Use the actual return and shipment status.\",\"title\":\"Check status\"},{\"text\":\"Use the available authorized exchange actions and do not promise an outcome not recorded in the system.\",\"title\":\"Continue the workflow\"}]"::jsonb,210),
("rto","Understand RTO","Use actual shipment and return records when handling return-to-origin cases.","[{\"text\":\"Review the real courier status and shipment events.\",\"title\":\"Check shipment status\"},{\"text\":\"Use the recorded RTO or return reason when available.\",\"title\":\"Review RTO information\"},{\"text\":\"Create a support ticket when the real shipment record does not answer the issue.\",\"title\":\"Escalate missing information\"}]"::jsonb,220)
on conflict do nothing;